export function tripBookVisits(records,journeyId){return records.flatMap(record=>visitsOf(record).filter(v=>v.tripIds?.includes(journeyId)).map(v=>visitView(record,v.id))).sort((a,b)=>a.visited.localeCompare(b.visited)||a.title.localeCompare(b.title)||a.visitId.localeCompare(b.visitId));}
